import asyncio
from typing import Any, Dict, Optional, Text, Tuple

import structlog
from pymilvus import MilvusClient

from rasa.core.information_retrieval import (
    InformationRetrieval,
    InformationRetrievalException,
    SearchResultList,
)
from rasa.core.information_retrieval.models import Document
from rasa.shared.providers.embedding.embedding_utils import aembed_query
from rasa.utils.endpoints import EndpointConfig

logger = structlog.get_logger()

DEFAULT_SEARCH_K = 4
# Fallback when the collection index does not advertise a metric.
DEFAULT_METRIC_TYPE = "L2"
# Metrics where a higher score means a better match (similarity). Every other
# metric (L2, HAMMING, JACCARD, ...) is a distance where lower is better.
SIMILARITY_METRIC_TYPES = frozenset({"IP", "COSINE"})
CONTENT_FIELD = "text"
VECTOR_FIELD = "vector"
METADATA_FIELD = "metadata"
DISTANCE_FIELD = "distance"
ENTITY_FIELD = "entity"


def _passes_threshold(score: float, threshold: float, metric_type: Text) -> bool:
    """Return whether ``score`` clears ``threshold`` for the given metric.

    Milvus returns similarities for ``IP``/``COSINE`` (higher is better) and
    distances for ``L2`` and the binary metrics (lower is better), so the
    comparison direction depends on the metric.
    """
    if metric_type.upper() in SIMILARITY_METRIC_TYPES:
        return score >= threshold
    return score <= threshold


class Milvus_Store(InformationRetrieval):
    """Milvus Store implementation backed by the native ``pymilvus`` client."""

    def connect(self, config: EndpointConfig) -> None:
        """Connect to the Milvus system."""
        params = config.kwargs
        self.collection_name = str(params.get("collection"))
        self._metric_type: Optional[Text] = None

        host = str(params.get("host"))
        port = str(params.get("port"))
        uri = params.get("uri") or f"http://{host}:{port}"

        client_kwargs: Dict[str, Any] = {"uri": uri}
        if params.get("user") is not None:
            client_kwargs["user"] = str(params.get("user"))
        if params.get("password") is not None:
            client_kwargs["password"] = str(params.get("password"))
        if params.get("token") is not None:
            client_kwargs["token"] = str(params.get("token"))
        if params.get("db_name") is not None:
            client_kwargs["db_name"] = str(params.get("db_name"))

        self.client = MilvusClient(**client_kwargs)

    def _resolve_metric_type(self) -> Text:
        """Return the metric configured on the collection vector index.

        Matches LangChain's behaviour of reading ``metric_type`` from the
        existing index rather than hard-coding a search metric. Falls back to
        ``DEFAULT_METRIC_TYPE`` when no index (or metric) is available.
        """
        if self._metric_type is not None:
            return self._metric_type

        try:
            metric_type = DEFAULT_METRIC_TYPE
            index_names = self.client.list_indexes(
                self.collection_name, field_name=VECTOR_FIELD
            )
            if index_names:
                index_info = (
                    self.client.describe_index(self.collection_name, index_names[0])
                    or {}
                )
                metric_type = str(index_info.get("metric_type") or DEFAULT_METRIC_TYPE)
        except Exception:
            # Metric resolution is best-effort: never let it break search. Return
            # the default without caching so a transient failure can recover on
            # the next search.
            logger.warning(
                "information_retrieval.milvus_store.metric_type_resolution_failed",
                collection=self.collection_name,
                fallback_metric_type=DEFAULT_METRIC_TYPE,
                exc_info=True,
            )
            return DEFAULT_METRIC_TYPE

        self._metric_type = metric_type
        logger.debug(
            "information_retrieval.milvus_store.resolved_metric_type",
            metric_type=metric_type,
            collection=self.collection_name,
        )
        return metric_type

    @staticmethod
    def _hit_to_document(hit: Dict[str, Any]) -> Tuple[Document, float]:
        distance = float(hit.get(DISTANCE_FIELD, 0.0))
        entity = hit.get(ENTITY_FIELD, {}) or {}
        text = entity.get(CONTENT_FIELD, "")
        metadata = entity.get(METADATA_FIELD)
        if metadata is None:
            metadata = {
                key: value
                for key, value in entity.items()
                if key not in (CONTENT_FIELD, VECTOR_FIELD)
            }
        return Document(text=text, metadata=metadata), distance

    async def search(
        self, query: Text, tracker_state: Dict[str, Any], threshold: float = 0.0
    ) -> SearchResultList:
        """Search for documents in the Milvus store.

        Args:
            query: The query to search for.
            tracker_state: The state of the tracker (unused by Milvus).
            threshold: the score cut-off for considering a document a match. The
                comparison direction follows the collection's metric: for
                distance metrics (``L2`` and the binary metrics) a match needs
                ``score <= threshold``; for similarity metrics (``IP``,
                ``COSINE``) a match needs ``score >= threshold``.

        Returns:
            A list of documents that match the query.
        """
        logger.debug("information_retrieval.milvus_store.search", query=query)
        metric_type = self._resolve_metric_type()
        try:
            # Embed the query using the embedding client
            embedding = await aembed_query(self.embeddings, query)
            # Search for the embedding in the Milvus collection
            raw_results = await asyncio.to_thread(
                self.client.search,
                collection_name=self.collection_name,
                data=[embedding],
                limit=DEFAULT_SEARCH_K,
                search_params={"metric_type": metric_type},
                output_fields=["*"],
            )
        except Exception as exc:
            raise InformationRetrievalException from exc

        # ``search`` returns one result list per query vector.
        hits = raw_results[0] if raw_results else []
        docs_with_scores = [self._hit_to_document(hit) for hit in hits]

        scores = [score for _, score in docs_with_scores]
        logger.debug(
            "information_retrieval.milvus_store.search_results_before_threshold",
            scores=scores,
            metric_type=metric_type,
        )
        filtered_hits = [
            doc
            for doc, score in docs_with_scores
            if _passes_threshold(score, threshold, metric_type)
        ]
        return SearchResultList.from_document_list(filtered_hits)
